<?php
declare(strict_types=1);
function cbSubjectDirectory(PDO $db):void{
    $code=trim((string)($_GET['subject']??''));$title=trim((string)($_GET['title']??''));
    $q=mb_substr(trim((string)($_GET['q']??'')),0,100);
    $where='1=1';$args=[];
    if($code!==''){$where.=' AND s.subject_code=?';$args[]=$code;if($title!==''){$where.=' AND s.subject_title=?';$args[]=$title;}}
    if($q!==''){$where.=" AND CONCAT_WS(' ',s.subject_code,s.subject_title,p.full_name,s.section) LIKE ?";$args[]='%'.$q.'%';}
    $state=(string)($_GET['state']??'');if(in_array($state,['draft','submitted','released'],true)){$where.=' AND c.state=?';$args[]=$state;}elseif($state==='archived')$where.=' AND c.archived=1';
    $from=' FROM subjects s JOIN professors p ON p.id=s.professor_id LEFT JOIN classbook_settings c ON c.subject_id=s.id WHERE '.$where;
    ?><link rel="stylesheet" href="assets/css/class-workspace.css?v=<?=filemtime(__DIR__.'/../assets/css/class-workspace.css')?>"><div class="class-workspace">
    <?php if($code!==''):?><div class="class-heading"><div><span class="eyebrow"><?=h($code)?></span><h2><?=h($title?:$code)?></h2><p>Select the professor and section to open its student masterlist.</p></div><div class="actions"><a class="button secondary" href="registrar.php?view=classes" aria-label="Back to subjects" title="Back to subjects"><?=portalIcon('arrow-right')?>Back to subjects</a></div></div><?php endif;?>
    <form method="get" class="admin-filters" data-auto-filter><input type="hidden" name="view" value="classes"><?php if($code!==''):?><input type="hidden" name="subject" value="<?=h($code)?>"><input type="hidden" name="title" value="<?=h($title)?>"><?php endif;portalField($code===''?'Search subjects':'Search professor or section','q',$q,'search');?><noscript><button class="icon-action" aria-label="Search" title="Search"><?=portalIcon('search')?></button></noscript></form>
    <?php portalFilterSummary([$q!==''?'Search: '.$q:''],$code!==''?'registrar.php?'.http_build_query(['view'=>'classes','subject'=>$code,'title'=>$title]):'registrar.php?view=classes');if($code===''){
        $groups=' GROUP BY s.subject_code,s.subject_title';$total=(int)cbQuery($db,'SELECT COUNT(*) FROM (SELECT s.subject_code,s.subject_title'.$from.$groups.') grouped',$args)->fetchColumn();
        $page=min(max(1,(int)($_GET['page']??1)),max(1,(int)ceil($total/18)));
        $rows=cbQuery($db,'SELECT s.subject_code,s.subject_title,COUNT(DISTINCT s.professor_id) AS professors,COUNT(*) AS sections'.$from.$groups.' ORDER BY s.subject_code,s.subject_title LIMIT 18 OFFSET '.(($page-1)*18),$args)->fetchAll();
        ?><div class="subject-grid"><?php foreach($rows as $row):$target='registrar.php?'.http_build_query(['view'=>'classes','subject'=>$row['subject_code'],'title'=>$row['subject_title']]);?><article class="subject-card"><span class="subject-symbol"><?=portalIcon('book-open')?></span><span class="eyebrow"><?=h($row['subject_code'])?></span><h2><a href="<?=h($target)?>"><?=h($row['subject_title'])?></a></h2><p><?=(int)$row['professors']?> <?=$row['professors']==1?'professor':'professors'?> · <?=(int)$row['sections']?> <?=$row['sections']==1?'class section':'class sections'?></p><a class="button secondary subject-open-link" href="<?=h($target)?>" aria-label="<?=h('View professors for '.$row['subject_code'])?>" title="View professors"><?=portalIcon('users')?>View professors</a></article><?php endforeach;?></div><?php if(!$rows)portalNotice('No subjects match your filters.');cbPager($page,$total,18);
    }else{
        $total=(int)cbQuery($db,'SELECT COUNT(*)'.$from,$args)->fetchColumn();$page=min(max(1,(int)($_GET['page']??1)),max(1,(int)ceil($total/25)));
        $rows=cbQuery($db,"SELECT s.*,p.full_name,p.department,c.state,c.archived,(SELECT COUNT(*) FROM enrollments e LEFT JOIN classbook_members m ON m.enrollment_id=e.id WHERE e.subject_id=s.id AND COALESCE(m.status,'active')='active') AS students".$from.' ORDER BY p.full_name,s.section LIMIT 25 OFFSET '.(($page-1)*25),$args)->fetchAll();
        ?><section class="card"><div class="masterlist-top" style="margin-bottom:16px"><div><h2>Assigned professors &amp; sections <span class="count-tag"><?=$total?></span></h2><p>Open a class section to review its student masterlist or verify submitted grade sheets.</p></div></div><div class="masterlist-scroll"><table><thead><tr><th>Professor</th><th>Section / term</th><th>Students</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><strong><?=h($row['full_name'])?></strong><small><?=h($row['department'])?></small></td><td><?=h($row['section'])?><small><?=h($row['school_year'].' · '.$row['semester'])?></small></td><td><?=(int)$row['students']?></td><td><?=cbAdminStatus($row['state']??'legacy')?><?php if($row['archived']):?> <?=cbAdminStatus('archived')?><?php endif;?></td><td><a class="icon-action" href="class.php?subject_id=<?=(int)$row['id']?>" aria-label="<?=h('Open masterlist: '.$row['full_name'].' '.$row['section'])?>" title="Student masterlist"><?=portalIcon('users')?></a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows)portalNotice('No class offerings match your filters.');cbPager($page,$total);?></section><?php
    }?></div><?php
}
